import{_ as c,C as l,o as i,c as n,ak as r,E as o,j as d,a}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"MatrixCode 二维码","description":"","frontmatter":{},"headers":[],"relativePath":"components/matrix-code.md","filePath":"components/matrix-code.md","lastUpdated":1790043131000}'),h={name:"components/matrix-code.md"};function s(u,t,b,m,x,p){const e=l("XhDemo");return i(),n("div",null,[t[0]||(t[0]=r('<h1 id="matrixcode-二维码" tabindex="-1">MatrixCode 二维码 <a class="header-anchor" href="#matrixcode-二维码" aria-label="Permalink to &quot;MatrixCode 二维码&quot;">​</a></h1><p>将一段文本绘制为二维码，<code>format</code> 选择码制。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/matrix-code" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/matrix-code.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/matrix-code" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/matrix-code" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/matrix-code.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>提供 value 即绘制码，版本按内容长度自动选择；默认 M 级纠错、4 个模块的静区</p>',5)),o(e,{src:"matrix-code/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;matrix-code&quot;</code>：<strong><code>root</code></strong> · <code>logo</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="码制" tabindex="-1">码制 <a class="header-anchor" href="#码制" aria-label="Permalink to &quot;码制&quot;">​</a></h3><p>qr 之外还有三种：工业打标用的 Data Matrix（rectangular 从矩形尺寸中选择）、运单证件用的 PDF417、票务用的 Aztec</p>',6)),o(e,{src:"matrix-code/02-format"}),t[2]||(t[2]=d("h3",{id:"纠错级别",tabindex:"-1"},[a("纠错级别 "),d("a",{class:"header-anchor",href:"#纠错级别","aria-label":'Permalink to "纠错级别"'},"​")],-1)),t[3]||(t[3]=d("p",null,"L / M / Q / H 依次能容忍更多污损，同样的内容也因此占用更多模块",-1)),o(e,{src:"matrix-code/03-level"}),t[4]||(t[4]=d("h3",{id:"边长与静区",tabindex:"-1"},[a("边长与静区 "),d("a",{class:"header-anchor",href:"#边长与静区","aria-label":'Permalink to "边长与静区"'},"​")],-1)),t[5]||(t[5]=d("p",null,"pixelSize 是整块的像素边长；margin 的单位是模块数，静区含在其中不额外占用空间",-1)),o(e,{src:"matrix-code/04-size-margin"}),t[6]||(t[6]=d("h3",{id:"可及名字",tabindex:"-1"},[a("可及名字 "),d("a",{class:"header-anchor",href:"#可及名字","aria-label":'Permalink to "可及名字"'},"​")],-1)),t[7]||(t[7]=d("p",null,"默认使用 value 作为 aria-label；内容不适合朗读时用 label 替换为可读文案",-1)),o(e,{src:"matrix-code/05-label"}),t[8]||(t[8]=d("h3",{id:"码点形状",tabindex:"-1"},[a("码点形状 "),d("a",{class:"header-anchor",href:"#码点形状","aria-label":'Permalink to "码点形状"'},"​")],-1)),t[9]||(t[9]=d("p",null,"square / dot / rounded；三种形状的墨迹都覆盖每个模块的格心，读码器按格心取样",-1)),o(e,{src:"matrix-code/06-module-shape"}),t[10]||(t[10]=d("h3",{id:"码眼形状",tabindex:"-1"},[a("码眼形状 "),d("a",{class:"header-anchor",href:"#码眼形状","aria-label":'Permalink to "码眼形状"'},"​")],-1)),t[11]||(t[11]=d("p",null,"只作用于三个定位图形，7×7 的外环加内心结构保持不变，读码器依靠它定位码",-1)),o(e,{src:"matrix-code/07-eye-shape"}),t[12]||(t[12]=d("h3",{id:"中心-logo",tabindex:"-1"},[a("中心 logo "),d("a",{class:"header-anchor",href:"#中心-logo","aria-label":'Permalink to "中心 logo"'},"​")],-1)),t[13]||(t[13]=d("p",null,"落位与尺寸由组件给出，该片模块先被底色挖空；放置 logo 后把 level 提到 Q 或 H",-1)),o(e,{src:"matrix-code/08-logo"}),t[14]||(t[14]=d("h3",{id:"换色",tabindex:"-1"},[a("换色 "),d("a",{class:"header-anchor",href:"#换色","aria-label":'Permalink to "换色"'},"​")],-1)),t[15]||(t[15]=d("p",null,"颜色不是 props，写三个 CSS 变量即可：码点必须比底色深且对比充足，反相码部分读码器不识别",-1)),o(e,{src:"matrix-code/09-color"}),t[16]||(t[16]=d("h3",{id:"gs1",tabindex:"-1"},[a("GS1 "),d("a",{class:"header-anchor",href:"#gs1","aria-label":'Permalink to "GS1"'},"​")],-1)),t[17]||(t[17]=d("p",null,"gs1 开启后最前面放置 FNC1，读码器把内容视为 GS1 元素串：变长 AI 后面用 GS（U+001D）与下一个隔开；医药 UDI 用 GS1 DataMatrix，零售 2D 迁移用 GS1 QR",-1)),o(e,{src:"matrix-code/10-gs1"}),t[18]||(t[18]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>跨设备传递地址、配对码：<code>qr</code>。</li><li>工业零件打标、电子元件、医药 UDI、追溯标签等需要在很小面积内放码的场景：<code>data-matrix</code>。</li><li>运单、证件、登机牌等需要放几百字节且只能横向扫描的场景：<code>pdf417</code>。</li><li>车票、登机牌、票务等需要在低分辨率下可扫、边缘无法留静区的场景：<code>aztec</code>。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>用户就在当前设备上时，提供可点击的链接。</li><li>内容很长时二维码过密无法扫描，改用短链。</li><li>只有几十个字符的货号、运单号需要扫描枪一次读出时，使用<a href="./bar-code">条形码</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>format</code> 支持四种码制：<code>qr</code>（默认，ISO/IEC 18004）、<code>data-matrix</code>（ISO/IEC 16022，含 2024 版并入的矩形扩展）、<code>pdf417</code>（ISO/IEC 15438）、<code>aztec</code>（ISO/IEC 24778）；未知值不绘制，根进入 error 状态。</li><li><code>gs1</code> 把码变为 GS1 QR / GS1 DataMatrix：最前面放 FNC1，变长 AI 之间用内容中的 GS（U+001D）分隔。</li><li><code>level</code> 的取值域随码制变化：QR 四档 L / M / Q / H，越高越能容忍污损，同样的内容也占更多模块；PDF417 九档 0–8，默认按数据量取规范推荐档；Aztec 是纠错码字至少占的百分比 5–95，默认 33。传入码制不支持的值时不绘制。</li><li>QR：<code>eyeShape</code> 切换码眼形状；中心可以放 logo。</li><li>Data Matrix：纠错率随尺寸固定，没有级别可选；<code>rectangular</code> 从矩形尺寸中选择，适合窄条标签；没有码眼，L 形定位图形随码点形状一起变化。</li><li>PDF417：<code>columns</code> 指定数据列数 1–30，默认选择宽高比最接近 3:1 的一档；它是条不是点，不接受 <code>moduleShape</code>。</li><li>Aztec：牛眼居中，不需要静区，默认 <code>margin</code> 为 0。</li><li><code>moduleShape</code> 切换码点形状；三种形状的墨都覆盖每个模块的格心，读码器按格心取样。</li><li><code>margin</code> 是静区，默认取码制的规范值；<code>pixelSize</code> 是宽度，高度按模块比例计算。</li><li>配色可替换。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>外层放<a href="./card">卡片</a>；旁边配<a href="./clipboard">剪贴板</a>提供同一内容的文本形式。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>放置 logo 时把纠错级别提到 Q 或 H，否则被遮住的模块无法恢复。</li><li>保留静区，贴边的码无法扫描；Data Matrix 需要一格，PDF417 两格，QR 四格，Aztec 不需要。</li><li>同时给出文本或链接，不是所有人都能扫描。</li><li>对当前码制无意义的选项（给 Data Matrix 传 <code>level</code>、给 QR 传 <code>rectangular</code>、给 PDF417 传 <code>moduleShape</code>）会向诊断通道报一条警告并按未提供处理，不依赖它们切换码制。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>深色主题下直接反色：读码器默认深码点浅底，反色的码很多设备无法扫描。</li><li>二维码印得过小。</li><li>给 Data Matrix 放 logo：它没有可选的纠错级别，被遮住的部分无法恢复，组件按未放置处理。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-matrix-code&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMatrixCode</code> <code>XhMatrixCodeLogo</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/matrix-code.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>number</code></td><td></td><td>PDF417 的数据列数 1–30，默认在宽高比最接近 3:1 的档位中选择。 只对 pdf417 有意义，其他码制提供时向诊断通道报告一条警告，按未提供处理。</td></tr><tr><td><code>eyeShape</code></td><td><code>MatrixCodeEyeShape</code></td><td></td><td>码眼形状，默认 square。时序图形与校正图形不受它影响，一律保持方块：它们是透视校正的几何基准。 只对 qr 有意义，其他码制提供时向诊断通道报告一条警告，按未提供处理。</td></tr><tr><td><code>format</code></td><td><code>MatrixCodeFormat</code></td><td></td><td>码制，默认 qr。提供未知值时不绘制，根落到 <code>error</code> 态。</td></tr><tr><td><code>gs1</code></td><td><code>boolean</code></td><td></td><td>GS1 模式：在最前面放置 FNC1，读码器据此把内容解释为 GS1 元素串，即 GS1 QR / GS1 DataMatrix； 变长 AI 之间用内容中的 GS（U+001D）分隔。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>可及名，默认使用 value；提供全空白的名字等同于未提供。</td></tr><tr><td><code>level</code></td><td><code>MatrixCodeLevel</code></td><td></td><td>纠错级别，取值域随码制：qr 为 L / M / Q / H（默认 M）；pdf417 为 0–8（默认按数据量取规范推荐档）； aztec 为纠错码字至少占的百分比 5–95（默认 33）。提供码制不识别的值时不绘制，根落到 <code>error</code> 态。 data-matrix 没有级别可选，提供时向诊断通道报告一条警告，按未提供处理。</td></tr><tr><td><code>logo</code></td><td><code>boolean</code></td><td></td><td>码面正中是否留出一块给 logo。 留出的模块会被底色覆盖，对读码器而言等于人为污损：放置 logo 时把 level 提到 Q 或 H， L 与 M 的纠错余量不足以承担这一块。损伤量见 <code>logoDamage</code>；超出所选级别的余量时 向诊断通道报告一条 <code>matrix-code.logo-damage</code> 警告，码照常绘制。 只对 qr 有意义：Data Matrix 的纠错余量随尺寸固定、没有可选的级别，放置 logo 会报告一条警告并按未放置处理。</td></tr><tr><td><code>margin</code></td><td><code>number</code></td><td></td><td>静区宽度，单位为模块数，默认按码制的规范值（qr 4、data-matrix 1）；静区含在 viewBox 中，不占额外尺寸。</td></tr><tr><td><code>moduleShape</code></td><td><code>MatrixCodeModuleShape</code></td><td></td><td>码点形状，默认 square。pdf417 是条不是点，提供时向诊断通道报告一条警告，按未提供处理。</td></tr><tr><td><code>pixelSize</code></td><td><code>number</code></td><td></td><td>像素宽度，默认 160；高度按模块比例计算，正方形码宽高相等。两者都写为根上的内联尺寸。</td></tr><tr><td><code>rectangular</code></td><td><code>boolean</code></td><td></td><td>从矩形尺寸（含矩形扩展 DMRE）中选择，默认从正方形尺寸中选择。 只对 data-matrix 有意义，其他码制提供时向诊断通道报告一条警告，按未提供处理。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>要编码的内容；空串不绘制。QR 按 UTF-8 取字节使用字节模式；Data Matrix 使用 ASCII 模式，Latin-1 以外的字符按 UTF-8 并声明 ECI。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;empty&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>MatrixCodeFormat</code></td><td>解析后的码制。提供未知值时原样透出，使错误信息与 data-format 都指向该值。</td></tr><tr><td><code>modules</code></td><td><code>readonly (readonly boolean[])[]</code></td><td>模块矩阵，[行][列]，true = 深色；未绘制时为空数组。</td></tr><tr><td><code>version</code></td><td><code>number</code></td><td>QR 实际使用的版本；其他码制与未绘制时为 0。</td></tr><tr><td><code>columns</code></td><td><code>number</code></td><td>模块列数与行数，不含静区；正方形码两者相等，pdf417 的行数已含每个码字行占的 3 个模块高，未绘制时为 0。</td></tr><tr><td><code>rows</code></td><td><code>number</code></td><td></td></tr><tr><td><code>margin</code></td><td><code>number</code></td><td>解析后的静区宽度，单位为模块数。</td></tr><tr><td><code>viewBox</code></td><td><code>string</code></td><td>根的 viewBox，含静区。</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>除 QR 三个码眼以外的模块合成的 <code>&amp;lt;path&amp;gt;</code> 的 d；未绘制时为空串，此时不应生成 path 节点。 码眼永远不在这一条中，与形状无关。</td></tr><tr><td><code>eyePath</code></td><td><code>string</code></td><td>QR 三个码眼合成的 <code>&amp;lt;path&amp;gt;</code> 的 d；其他码制与未绘制时为空串，此时不应生成第二个 path 节点。 两条分开绘制与形状无关：码眼的颜色可以与码点不同，合成一条就无法单独上色。</td></tr><tr><td><code>logoArea</code></td><td><code>MatrixCodeLogoArea | undefined</code></td><td>logo 的落位与挖空矩形；未留位时为 undefined。</td></tr><tr><td><code>logoDamage</code></td><td><code>MatrixCodeLogoDamage | undefined</code></td><td>挖空对码面造成的损伤；未留 logo 位时为 undefined。</td></tr><tr><td><code>state</code></td><td><code>MatrixCodeState</code></td><td>当前状态。</td></tr><tr><td><code>error</code></td><td><code>string | undefined</code></td><td>编码失败的原因；其余状态为 undefined。</td></tr><tr><td><code>label</code></td><td><code>string | undefined</code></td><td>解析后的可及名；未提供名字时为 undefined，此时根退出无障碍树。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLogoProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>铺到 logo 部件上的落位；未留位时宽高都是 0，该块连同其中的图形一起不渲染。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/names-and-descriptions/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>aria-label</code></td><td>undefined | props.label</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>undefined | &#39;img&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/matrix-code.css</code> 使用 <code>[data-scope=&quot;matrix-code&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-columns</code></td><td>undefined | String(columns)</td></tr><tr><td><code>root</code></td><td><code>data-format</code></td><td>props.format</td></tr><tr><td><code>root</code></td><td><code>data-level</code></td><td>&#39;M&#39; | String(pdfLevel) | undefined</td></tr><tr><td><code>root</code></td><td><code>data-logo</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-rows</code></td><td>undefined | String(rows)</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>root</code></td><td><code>data-version</code></td><td>undefined | String(version)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-matrix-code-bg</code></td><td><code>root</code></td><td><code>background</code><br><code>fill</code></td><td><code>default</code><br><code>xh-geom=logo-clear</code></td><td><code>--xh-color-neutral-0</code></td><td>matrix-code 的 root 部件 background、fill 覆盖槽。</td></tr><tr><td><code>--xh-matrix-code-eye-fg</code></td><td><code>root</code></td><td><code>fill</code></td><td><code>xh-geom=eyes</code></td><td><code>currentColor</code></td><td>matrix-code 的 root 部件 fill 覆盖槽。</td></tr><tr><td><code>--xh-matrix-code-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-color-neutral-950</code></td><td>matrix-code 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-matrix-code-placeholder-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>state=empty</code><br><code>state=error</code></td><td><code>--xh-bg-subtle</code></td><td>matrix-code 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-matrix-code-placeholder-border</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>state=empty</code><br><code>state=error</code></td><td><code>--xh-border-default</code></td><td>matrix-code 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-matrix-code-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>matrix-code 的 root 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>box-shadow</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p>',43))])}const q=c(h,[["render",s]]);export{f as __pageData,q as default};
